                    if (m_pRenderer->IsStreaming() && !m_pRenderer->IsEndOfStreamDelivered()) {
                        m_pRenderer->NotifyEndOfStream();
                    }
                }

                m_bRunTimeError = 1;
            }
        }
    }

    return hr;
}

