HRESULT __stdcall CBaseAllocator::Commit()
{
    /* Check we are not decommitted */
    CAutoLock cObjectLock(this);

    // cannot need to alloc or free if we are committed
    if (m_bCommitted) {
        return 0;
    }

    /* Allow GetBuffer calls */
    m_bCommitted = 1;

    // is there a pending decommit ? if so, just cancel it
    if (m_bDecommitInProgress) {
        m_bDecommitInProgress = 0;
        return 0;
    }

    // actually need to allocate the samples
    HRESULT hr = Alloc();
    if (hr < 0) {
        m_bCommitted = 0;
        return hr;
    }
    AddRef();
    return 0;
}

